using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class CDAudit {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_CeilingDensity/";static string O=>R+"/Docs/Review/2026-11-10_B2_CeilingDensity/";
 static JObject Plan()=>JObject.Parse(File.ReadAllText(H+"plan.json"));static Vector3 V(JToken a)=>new Vector3((float)a[0],(float)a[1],(float)a[2]);
 static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");Directory.CreateDirectory(O);return s;}
 static Vector3 Offset(JToken r)=>new Vector3((float)r["x"],-34,-(float)r["v"]);
 static object Move(CharacterController cc,Vector3[] points,float h){bool ok=true;float miss=0,feet=0;int index=0;cc.enabled=false;cc.height=h;cc.center=new Vector3(0,h*.5f,0);cc.transform.position=points[0]+Vector3.up*.035f;cc.enabled=true;Physics.SyncTransforms();for(int j=1;j<points.Length;j++){index=j;for(int k=0;k<30;k++){var delta=points[j]-cc.transform.position;delta.y=0;miss=delta.magnitude;if(miss<.035f)break;cc.Move(delta.normalized*Mathf.Min(.06f,miss)+Vector3.down*.025f);}for(int k=0;k<15;k++)if((cc.Move(Vector3.down*.035f)&CollisionFlags.Below)!=0)break;feet=cc.transform.position.y;if(miss>.13f||Math.Abs(feet-points[j].y)>.28f){ok=false;break;}}cc.enabled=false;return new{passed=ok,miss,feet,expected=points[index].y,index,position=new[]{cc.transform.position.x,cc.transform.position.y,cc.transform.position.z}};}
 public static object Ground(){var s=Check();var plan=Plan();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var rows=new List<object>();var paths=new JArray();var old=player.transform.position;float oh=cc.height;var oc=cc.center;bool en=cc.enabled;try{cc.enabled=false;Physics.SyncTransforms();foreach(var room in plan["rooms"]){string id=(string)room["id"];if(!GameObject.Find("B2_"+id+"_Operations"))continue;var origin=Offset(room);float radius=(float)room["r"];const float step=.30f;int n=Mathf.CeilToInt(radius/step);var free=new HashSet<Vector2Int>();for(int x=-n;x<=n;x++)for(int z=-n;z<=n;z++){if(x*x*step*step+z*z*step*step>(radius-.55f)*(radius-.55f))continue;var pos=origin+new Vector3(x*step,0,z*step);if(!Physics.CheckCapsule(pos+Vector3.up*.37f,pos+Vector3.up*1.48f,.30f,~0,QueryTriggerInteraction.Ignore)&&Physics.Raycast(pos+Vector3.up*.25f,Vector3.down,.5f,~0,QueryTriggerInteraction.Ignore))free.Add(new Vector2Int(x,z));}
 Func<Vector3,Vector2Int> nearest=goal=>free.OrderBy(q=>(new Vector2(q.x*step,q.y*step)-new Vector2(goal.x,goal.z)).sqrMagnitude).First();var first=room["doors"].First();var start=nearest(new Vector3((float)first["x"],0,(float)first["z"]));var prev=new Dictionary<Vector2Int,Vector2Int>();prev[start]=start;var queue=new Queue<Vector2Int>();queue.Enqueue(start);var ds=new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right};while(queue.Count>0){var q=queue.Dequeue();foreach(var di in ds){var q2=q+di;if(free.Contains(q2)&&!prev.ContainsKey(q2)){prev[q2]=q;queue.Enqueue(q2);}}}
 var targets=new List<object>();foreach(var d in room["doors"]){var goal=new Vector3((float)d["x"],0,(float)d["z"]);var q=nearest(goal);float error=Vector2.Distance(new Vector2(q.x*step,q.y*step),new Vector2(goal.x,goal.z));bool reachable=prev.ContainsKey(q)&&error<.6f;object move=null;if(reachable){var ps=new List<Vector3>();var at=q;while(at!=start){ps.Add(origin+new Vector3(at.x*step,0,at.y*step));at=prev[at];}ps.Add(origin+new Vector3(start.x*step,0,start.y*step));ps.Reverse();if(ps.Count>1)move=Move(cc,ps.ToArray(),1.8f);paths.Add(new JObject{["name"]=id+"_"+(string)d["id"],["points"]=JArray.FromObject(ps.Select(v=>new[]{v.x,v.y,v.z}))});}targets.Add(new{name=(string)d["id"],kind="door",reachable,error,move});}
 foreach(var p in plan["placements"].Where(p=>(string)p["room"]==id)){var rot=Quaternion.Euler(0,(float)p["yaw"],0);var goal=V(p["position"])+rot*(new Vector3((float)p["center"][0],0,(float)p["center"][2])+Vector3.forward*((float)p["size"][2]*.5f+.60f));var q=nearest(goal);float error=Vector2.Distance(new Vector2(q.x*step,q.y*step),new Vector2(goal.x,goal.z));targets.Add(new{name=(string)p["name"],kind="operatingFace",reachable=prev.ContainsKey(q)&&error<.55f,error});}
 rows.Add(new{id,free=free.Count,connected=prev.Count,targets});}
 }finally{cc.enabled=false;cc.height=oh;cc.center=oc;player.transform.position=old;cc.enabled=en;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}File.WriteAllText(O+"ground.json",JsonConvert.SerializeObject(rows,Formatting.Indented));File.WriteAllText(H+"ground_routes.json",paths.ToString());return new{rooms=rows.Count,report=O+"ground.json"};}
 public static object Upper(){var s=Check();var plan=Plan();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var old=player.transform.position;float oh=cc.height;var oc=cc.center;bool en=cc.enabled;var rows=new List<object>();try{cc.enabled=false;Physics.SyncTransforms();foreach(var r in plan["routes"]){string id=(string)r["room"];if(!GameObject.Find("B2_"+id+"_Operations"))continue;var room=plan["rooms"].Single(q=>(string)q["id"]==id);var offset=Offset(room);var ps=r["points"].Select(p=>V(p)+offset).ToArray();var points=new List<Vector3>();for(int i=1;i<ps.Length;i++){int n=Mathf.CeilToInt(Vector3.Distance(ps[i-1],ps[i])/.12f);for(int j=0;j<n;j++)points.Add(Vector3.Lerp(ps[i-1],ps[i],(float)j/n));}points.Add(ps.Last());var results=new[]{Move(cc,points.ToArray(),(float)r["height"]),Move(cc,points.AsEnumerable().Reverse().ToArray(),(float)r["height"])};rows.Add(new{name=(string)r["name"],moves=results});}}
 finally{cc.enabled=false;cc.height=oh;cc.center=oc;player.transform.position=old;cc.enabled=en;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}File.WriteAllText(O+"upper.json",JsonConvert.SerializeObject(rows,Formatting.Indented));return new{routes=rows.Count,report=O+"upper.json"};}
 static void Shot(string name,Vector3 pos,Vector3 target,float fov=80){var g=new GameObject("BO_ReviewCamera"){hideFlags=HideFlags.HideAndDontSave};var c=g.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.nearClipPlane=.04f;c.farClipPlane=180;c.fieldOfView=fov;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,900,24){antiAliasing=4};var old=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,900),0,0);tex.Apply();File.WriteAllBytes(O+name+".png",tex.EncodeToPNG());}finally{RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
 public static object Before()=>Capture("before");public static object After()=>Capture("after");
 public static object Close(){var s=Check();Shot("after_motor_bench",new Vector3(-96.2f,-32.35f,-30.7f),new Vector3(-96.2f,-32.7f,-32.18f),60);return "motor bench close-up";}
 static object Capture(string prefix){var s=Check();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool on=player.activeSelf;player.SetActive(false);try{foreach(var r in Plan()["rooms"]){string id=(string)r["id"];var origin=Offset(r);float rad=(float)r["r"];var d=r["doors"].First();var door=new Vector3((float)d["x"],0,(float)d["z"]);var pos=door.normalized*(rad-1.35f)+Vector3.up*1.65f;Shot(prefix+"_"+id,origin+pos,origin+new Vector3(0,1.9f,0));}
 if(prefix=="after"){Shot(prefix+"_C02_central",new Vector3(18.9f,-32.35f,-5.5f),new Vector3(19,-31.8f,4));Shot(prefix+"_E02_filter",new Vector3(124,-32.35f,1),new Vector3(126,-32,7));Shot(prefix+"_W03_repair",new Vector3(-94,-32.35f,-25),new Vector3(-94,-32.4f,-32));}}
 finally{player.SetActive(on);EditorSceneManager.OpenScene(s.path);}return new{prefix,images=prefix=="after"?15:12};}
 public static object Show(){Check();var temp=new GameObject("BO_View");temp.transform.position=new Vector3(19,-32.35f,-8.7f);temp.transform.LookAt(new Vector3(19,-29.8f,3));var view=SceneView.lastActiveSceneView??EditorWindow.GetWindow<SceneView>();view.orthographic=false;view.sceneLighting=true;view.drawGizmos=false;view.AlignViewToObject(temp.transform);view.Focus();UnityEngine.Object.DestroyImmediate(temp);Selection.activeGameObject=GameObject.Find("B2_C02_Operations");return "C02 operating aisle";}
}
